<template><section class="settings-group background-settings"><div class="settings-group-head"><h2>Фон</h2><p>Изменения видны сразу.</p></div><div class="background-layout"><div class="background-main"><div class="background-panel"><h3>Тип фона</h3><BackgroundChoices/></div><div class="background-panel"><h3>Цвет и рисунок</h3><BackgroundPresets/></div><div v-if="bg.mode==='beauty'" class="background-panel"><h3>Настройка рисунка</h3><div class="background-sliders"><SettingSlider label="Контраст" description="Разница между светлыми и тёмными участками." :model-value="ui.settings.metalContrast" :min="50" :max="220" :step="5" suffix="%" @update:model-value="ui.set('metalContrast',$event)"/><SettingSlider label="Скорость движения" description="Как быстро меняется рисунок." :model-value="ui.settings.metalSpeed" :min="5" :max="100" :step="5" suffix="%" @update:model-value="ui.set('metalSpeed',$event)"/><SettingSlider label="Глубина" description="Насколько выражены изгибы поверхности." :model-value="ui.settings.metalDepth" :min="20" :max="250" :step="5" suffix="%" @update:model-value="ui.set('metalDepth',$event)"/><SettingSlider label="Яркость отражений" description="Насколько заметны блики." :model-value="ui.settings.liquidIntensity" :min="15" :max="100" :step="5" suffix="%" @update:model-value="ui.set('liquidIntensity',$event)"/><SettingSlider label="Зернистость" description="Количество мелких точек на поверхности." :model-value="ui.settings.metalGrain" :min="0" :max="100" :step="5" suffix="%" @update:model-value="ui.set('metalGrain',$event)"/></div><SettingToggle label="Реакция на курсор" description="Фон немного смещается за курсором." :model-value="ui.settings.liquidParallax" @update:model-value="ui.set('liquidParallax',$event)"/><SettingToggle label="Движение фона" description="Зависит также от настройки анимаций в приложении и системе." :model-value="ui.settings.liquidMotion" @update:model-value="ui.set('liquidMotion',$event)"/><ColorField label="Цвет отражений" :value="ui.settings.metalAccent" @change="ui.set('metalAccent',$event)"/><div class="background-seed"><label>Номер рисунка<input type="number" min="0" max="99999" :value="ui.settings.metalSeed" @change="seed(($event.target as HTMLInputElement).value)"/></label><button class="btn" type="button" @click="randomize">Другой рисунок</button></div></div></div></div><p v-if="bg.error" role="alert" class="setup-error">{{bg.error}}</p></section></template>
<script setup lang="ts">
import {useBackgroundStore} from '@/stores/background';import {useUiStore} from '@/stores/ui';import BackgroundChoices from '@/components/background/BackgroundChoices.vue';import BackgroundPresets from '@/components/background/BackgroundPresets.vue';import SettingSlider from '../SettingSlider.vue';import SettingToggle from '../SettingToggle.vue';import ColorField from '../ColorField.vue';const bg=useBackgroundStore(),ui=useUiStore();
function seed(raw:string){const n=Number(raw);ui.set('metalSeed',Number.isFinite(n)?Math.round(Math.max(0,Math.min(99999,n))):42)}function randomize(){ui.set('metalSeed',crypto.getRandomValues(new Uint32Array(1))[0]%100000)}
</script>
